{
  "name": "opencode-agent-factory-plugin",
  "version": "1.0.0",
  "description": "Dynamic multi-agent orchestration for OpenCode. Analyzes prompts, generates specialized agents at runtime, executes in parallel with consensus strategies.",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "bun-types": "latest",
    "typescript": "^5.0.0"
  },
  "files": [
    "dist",
    "agents",
    "commands",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "multi-agent",
    "orchestration",
    "consensus",
    "parallel-agents",
    "dynamic-agents",
    "agent-factory",
    "dag"
  ],
  "license": "AGPL-3.0",
  "repository": {
    "type": "git",
    "url": "https://github.com/MunhozThiago/opencode-agent-factory-plugin"
  },
  "publishConfig": {
    "access": "public"
  },
  "opencode": {
    "name": "Agent Factory",
    "description": "Dynamic multi-agent orchestration with runtime agent generation and consensus protocols",
    "minVersion": "0.1.0"
  }
}
